SELECT id, version, title, content, published, published_at, created_at, updated_at FROM system_update_history WHERE 1=1
AND published = #{published}
AND ( title LIKE CONCAT('%', #{keyword}, '%') OR version LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY COALESCE(published_at, created_at) DESC, id DESC LIMIT #{offset}, #{size}

SELECT COUNT(1) FROM system_update_history WHERE 1=1
AND published = #{published}
AND ( title LIKE CONCAT('%', #{keyword}, '%') OR version LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%') )

SELECT id, version, title, content, published, published_at, created_at, updated_at
FROM system_update_history
WHERE id = #{id}
